// Fit complete upcoming-event rows into the desktop card instead of clipping a fixed count.
function upcomingVisibleCount(heights,available){let used=0,count=0;for(const height of heights){if(used+height>available+.5)break;used+=height;count++;}return count;}
(()=>{
 const list=$('dashEvents');if(!list)return;let queued=false;
 function fit(){queued=false;const rows=[...list.querySelectorAll(':scope>.eh-upcoming-row')];if(!rows.length){list.dataset.visibleEvents='0';list.dataset.totalEvents='0';return;}if(!list.clientWidth)return;rows.forEach(row=>row.hidden=false);if(innerWidth<=1000||list.closest('.hud-schedule-primary'))return;const style=getComputedStyle(list),available=list.clientHeight-parseFloat(style.paddingTop||0)-parseFloat(style.paddingBottom||0),heights=rows.map(row=>{const rect=row.getBoundingClientRect(),css=getComputedStyle(row);return rect.height+parseFloat(css.marginTop||0)+parseFloat(css.marginBottom||0);}),count=upcomingVisibleCount(heights,available);rows.forEach((row,index)=>row.hidden=index>=count);list.dataset.visibleEvents=String(count);list.dataset.totalEvents=String(rows.length);}
 function queue(){if(queued)return;queued=true;requestAnimationFrame(fit);}
 new ResizeObserver(queue).observe(list);new MutationObserver(queue).observe(list,{childList:true,subtree:true});window.addEventListener('resize',queue);document.fonts?.ready.then(queue);queue();
})();

